        call("POST", "/reservations/" + a.get("id").asLong() + "/confirmation", null);
        JsonNode da = call("GET", "/reservations/" + a.get("id").asLong() + "/document", null).json();
        assertEquals("Fatura de hospedagem", da.get("title").asText());
