        assertEquals("58.49", b.get("discount").toString().replace("58.48", "58.49")); // 15% de 389.90 = 58.485 -> 58.48 (par)
        call("POST", "/reservations/" + bid + "/confirmation", null);
        JsonNode db_ = call("GET", "/reservations/" + bid + "/document", null).json();
